const locales: TranslateCatalog = {
  de: de as Record<string, string>,
  tr,
  bg,
  ro,
  ru,
};

export function t(
  key: TranslationKey,
  lang: AppLanguage = 'de',
  params?: Record<string, string | number>,
): string {
  return translateKey(key, lang, locales, params);
}

